  "哀": [{w:"哀心",r:"애심",d:"슬프고 애달픈 마음."},{w:"哀感",r:"애감",d:"구슬프게 느끼는 데가 있음. 또는 그런 느낌."}],
  "若": [{w:"萬若",r:"만약",d:"혹시 있을지도 모르는 뜻밖의 경우."},{w:"老若",r:"노약",d:"늙은 사람과 약한 사람을 통틀어 이르는 말. ⇒규범 표기는 ‘노약’이다."}],
