  "憶": [{w:"記憶",r:"기억",d:"이전의 인상이나 경험을 의식 속에 간직하거나 도로 생각해 냄."},{w:"憶念",r:"억념",d:"마음속에 단단히 기억하여 잊지 아니함. 또는 그런 기억."}],
  "抑": [{w:"抑制",r:"억제",d:"감정이나 욕망, 충동적 행동 따위를 내리눌러서 그치게 함."},{w:"抑壓",r:"억압",d:"자기의 뜻대로 자유로이 행동하지 못하도록 억지로 억누름."}],
  "疫": [{w:"檢疫",r:"검역",d:"해외에서 감염병이나 해충이 들어오는 것을 막기 위하여 공항과 항구에서 하는 일들을 통틀어 이르는 말. 자동차·배·비행기·화물 따위를 검진하고 소독하며, 승객들에게 예방 주사를 접종하거나 병이 있는 사람을 격리하고, 동물이나 식물을 따로 보관하여 병의 유무를 살핀 뒤 폐기하거나 통과시키거나 하는 일 따위가 이에 속한다."},{w:"馬疫",r:"마역",d:"말의 돌림병."}],
  "亦": [{w:"亦然",r:"역연",d:"또한 그러함."},{w:"亦是",r:"역시",d:"어떤 것을 전제로 하고 그것과 같게."}],
  "役": [{w:"現役",r:"현역",d:"현재 어떠한 직무에 종사하고 있는 사람. 또는 현재 종사하고 있는 일."},{w:"軍役",r:"군역",d:"군대에서 복역하거나 군대의 진영(陣營)에서 부역하는 일."}],
