  "炎": [{w:"炎火",r:"염화",d:"세게 타오르는 불."},{w:"炎方",r:"염방",d:"몹시 더운 곳이라는 뜻으로, ‘남쪽’을 이르는 말."}],
  "影": [{w:"無影",r:"무영",d:"그림자가 없음."},{w:"山影",r:"산영",d:"산이 빛을 가려서 생기는 그림자."}],
