  "柔": [{w:"內柔",r:"내유",d:"속마음이나 성질이 부드러움."},{w:"溫柔",r:"온유",d:"성격, 태도 따위가 온화하고 부드러움."}],
  "維": [{w:"維持",r:"유지",d:"어떤 상태나 상황을 그대로 보존하거나 변함없이 계속하여 지탱함."},{w:"保維",r:"보유",d:"보존하여 유지함."}],
