  "翼": [{w:"右翼",r:"우익",d:"새나 비행기 따위의 오른쪽 날개."},{w:"左翼",r:"좌익",d:"새나 비행기 따위의 왼쪽 날개."}],
  "忍": [{w:"殘忍",r:"잔인",d:"인정이 없고 아주 모짊."},{w:"忍苦",r:"인고",d:"괴로움을 참음."}],
  "逸": [{w:"逸物",r:"일물",d:"아주 뛰어난 물건."},{w:"逸才",r:"일재",d:"보통보다 뛰어난 재주. 또는 그런 재주를 가진 사람."}],
  "壬": [{w:"壬人",r:"임인",d:"간사하고 아첨 잘하는 소인(小人)."},{w:"壬公",r:"임공",d:"‘물’을 달리 이르는 말. 오행(五行)에서 임(壬)은 물에 속한다."}],
