  "莊": [{w:"莊嚴",r:"장엄",d:"씩씩하고 웅장하며 위엄 있고 엄숙함."},{w:"莊土",r:"장토",d:"개인이 소유하는 논밭."}],
  "葬": [{w:"海葬",r:"해장",d:"바다에 장사 지냄."},{w:"葬後",r:"장후",d:"장사를 치른 뒤."}],
  "臟": [{w:"子臟",r:"자장",d:"‘자궁’을 한방에서 이르는 말."},{w:"心臟",r:"심장",d:"주기적인 수축에 의하여 혈액을 몸 전체로 보내는, 순환 계통의 중심적인 근육 기관. 어류는 1심방 1심실, 양서류는 2심방 1심실, 조류와 포유류는 2심방 2심실이다. 사람의 경우에는 가슴안에서 중앙보다 왼쪽에 있고, 주먹보다 약간 큰 근육질 덩어리로 원뿔형의 주머니 모양을 하고 있다."}],
  "粧": [{w:"化粧",r:"화장",d:"화장품을 바르거나 문질러 얼굴을 곱게 꾸밈."},{w:"治粧",r:"치장",d:"잘 매만져 곱게 꾸밈."}],
  "掌": [{w:"足掌",r:"족장",d:"발 아래쪽의, 땅을 밟는 평평한 부분."},{w:"拍掌",r:"박장",d:"두 손바닥을 마주침."}],
  "丈": [{w:"丈祖",r:"장조",d:"아내의 할아버지."},{w:"丈母",r:"장모",d:"아내의 어머니를 이르는 말."}],
  "藏": [{w:"藏氷",r:"장빙",d:"얼음을 떠서 곳간에 저장함. 또는 그 얼음."},{w:"冬藏",r:"동장",d:"가을의 수확물을 겨울 동안 저장함. 또는 그런 저장물."}],
  "栽": [{w:"栽培",r:"재배",d:"식물을 심어 가꿈."},{w:"栽揷",r:"재삽",d:"꺾꽂이를 하여 심음."}],
  "裁": [{w:"獨裁",r:"독재",d:"특정한 개인, 단체, 계급, 당파 따위가 어떤 분야에서 모든 권력을 차지하여 모든 일을 독단으로 처리함."},{w:"決裁",r:"결재",d:"결정할 권한이 있는 상관이 부하가 제출한 안건을 검토하여 허가하거나 승인함."}],
