  "傘": [{w:"雨傘",r:"우산",d:"우비(雨備)의 하나. 펴고 접을 수 있어 비가 올 때에 펴서 손에 들고 머리 위를 가린다. 박쥐우산, 비닐우산, 지우산 따위가 있다."},{w:"洋傘",r:"양산",d:"서양식의 헝겊 우산."}],
  "酸": [{w:"甘酸",r:"감산",d:"맛이 달고 심."},{w:"辛酸",r:"신산",d:"맛이 맵고 심."}],
  "蔘": [{w:"海蔘",r:"해삼",d:"해삼강의 동물을 일상적으로 통틀어 이르는 말. 몸은 부드럽고 오이 모양으로 온몸에 오톨도톨한 돌기가 많이 나 있으며, 검푸른 갈색 또는 검붉은 갈색이다. 살은 날로 먹고 말린 것은 요리에 쓰며 내장으로는 젓을 담근다. 한국, 일본 등지의 바다에 분포한다."},{w:"尾蔘",r:"미삼",d:"인삼의 잔뿌리를 약재나 식료품 또는 기호식품 따위의 재료로 이르는 말."}],
  "揷": [{w:"揷入",r:"삽입",d:"틈이나 구멍 사이에 다른 물체를 끼워 넣음."},{w:"揷床",r:"삽상",d:"꺾꽂이를 할 때, 꺾꽂이모를 꽂아 놓는 판."}],
  "箱": [{w:"箱子",r:"상자",d:"물건을 ‘상자’에 담아 그 분량을 세는 단위."},{w:"書箱",r:"서상",d:"책을 넣어 두는 궤짝."}],
