  "腎": [{w:"肝腎",r:"간신",d:"간장(肝臟)과 신장(腎臟)을 아울러 이르는 말."},{w:"腎虛",r:"신허",d:"하초(下焦)가 허약한 병. 과로나 지나친 성생활, 만성병으로 인하여 생기며 식은땀이 나거나 허리가 시큰거리고 유정(遺精), 발기 불능(勃起不能)의 증상이 있다."}],
