  "尉": [{w:"參尉",r:"참위",d:"대한 제국 때에 둔 위관 계급의 하나. 부위의 아래, 특무정교의 위이다."},{w:"准尉",r:"준위",d:"위관 계급의 하나. 소위의 아래, 원사의 위로 위관 계급에서 가장 낮은 계급이다."}],
