  "貳": [{w:"携貳",r:"휴이",d:"서로 다른 마음을 가짐. 즉 서로 어그러져 믿지 않음을 이른다."},{w:"岐貳",r:"기이",d:"의논이 일치하지 않고 여러 갈래로 나누어짐."}],
