  "妊": [{w:"妊婦",r:"임부",d:"아이를 밴 여자."},{w:"妊産",r:"임산",d:"아이를 배고 낳는 일."}],
  "磁": [{w:"磁北",r:"자북",d:"북반구에서 지구 자기의자력선의 방향이 수평면과 이루는 각이 90도인 지점."},{w:"磁束",r:"자속",d:"자기력선 다발. 자기장이 있는 공간에서 어떤 면적을 지나가는 자기력선의 총수에 비례하여 이것의 밀도와 수직인 면의 넓이를 곱한 양이다. 단위는 웨버(Wb)."}],
  "諮": [{w:"諮問",r:"자문",d:"어떤 일을 좀 더 효율적이고 바르게 처리하려고 그 방면의 전문가나, 전문가들로 이루어진 기구에 의견을 물음."},{w:"諮議",r:"자의",d:"남에게 의견을 물어 의논하는 일."}],
