  "偵": [{w:"探偵",r:"탐정",d:"드러나지 않은 사정을 몰래 살펴 알아냄. 또는 그런 일을 하는 사람."},{w:"偵探",r:"정탐",d:"드러나지 않은 사정을 몰래 살펴 알아냄. 또는 그런 일을 하는 사람."}],
