  "彫": [{w:"彫心",r:"조심",d:"마음에 새김."},{w:"彫石",r:"조석",d:"조각품이 새겨져 있는 돌."}],
  "綜": [{w:"綜合",r:"종합",d:"여러 가지를 한데 모아서 합함."},{w:"綜理",r:"종리",d:"빈틈없이 조리 있게 처리함."}],
