  "藿": [{w:"魚藿",r:"어곽",d:"물고기와 해조류를 통틀어 이르는 말."},{w:"藿耳",r:"곽이",d:"미역의 대가리."}],
  "棺": [{w:"木棺",r:"목관",d:"나무로 짠 관."},{w:"石棺",r:"석관",d:"돌로 만든 관."}],
  "顴": [{w:"下顴",r:"하관",d:"광대뼈를 중심으로 얼굴의 아래쪽 턱 부분."},{w:"顴骨",r:"관골",d:"뺨의 튀어나온 부분을 이루는 네모꼴의 뼈. 눈구멍 아래쪽 모서리를 이룬다."}],
  "灌": [{w:"浸灌",r:"침관",d:"물을 뿌리거나 부어서 적심."},{w:"湯灌",r:"탕관",d:"불교의 장사(葬事)에서, 관(棺)에 넣기 전에 시체를 목욕시키는 일."}],
  "刮": [{w:"刮目",r:"괄목",d:"눈을 비비고 볼 정도로 매우 놀람."},{w:"刮痧",r:"괄사",d:"혈액 순환을 돕기 위해 피부를 문지르거나 자극할 수 있도록 만든 기구. 중의학의 민간 요법에서 유래하였다."}],
  "括": [{w:"總括",r:"총괄",d:"개별적인 여러 가지를 한데 모아서 묶음."},{w:"一括",r:"일괄",d:"개별적인 여러 가지 것을 한데 묶음."}],
  "曠": [{w:"曠土",r:"광토",d:"황폐하고 거친 넓은 땅."},{w:"空曠",r:"공광",d:"텅 빔."}],
  "壙": [{w:"壙中",r:"광중",d:"시체가 놓이는 무덤의 구덩이 부분을 이르는 말."},{w:"壙內",r:"광내",d:"시체가 놓이는 무덤의 구덩이 부분을 이르는 말."}],
  "匡": [{w:"一匡",r:"일광",d:"어지러운 천하를 다스려 바로잡음."},{w:"加匡",r:"가광",d:"보충하여 바로잡음."}],
  "胱": [{w:"膀胱",r:"방광",d:"콩팥에서 흘러나오는 오줌을 저장하였다가 일정한 양이 되면 요도를 통하여 배출시키는 주머니 모양의 기관."},{w:"膀胱計",r:"방광계",d:"방광의 압력과 용적을 측정하여 방광의 효율성을 연구하는 데 쓰는 기계."}],
  "罫": [{w:"罫線",r:"괘선",d:"가로세로로 그은 선."},{w:"罫紙",r:"괘지",d:"미농지에 괘선을 박은 종이. 흔히, 공문서를 작성하는 데 쓴다."}],
