  "拐": [{w:"誘拐",r:"유괴",d:"사람을 속여서 꾀어냄."},{w:"拐帶",r:"괴대",d:"속임수를 써서 사람을 유괴하거나 물건을 가지고 달아남."}],
  "魁": [{w:"魁公",r:"괴공",d:"어떤 일이나 단체에서 으뜸인 사람."},{w:"魁頭",r:"괴두",d:"쪽을 찌거나 상투를 틀어 매지 않고 그냥 풀어 놓은 머리."}],
  "乖": [{w:"乖角",r:"괴각",d:"성질이 비꼬임."},{w:"乖反",r:"괴반",d:"어그러져 틀린 상태에 있음."}],
  "肱": [{w:"曲肱",r:"곡굉",d:"팔을 구부림."},{w:"枕肱",r:"침굉",d:"팔을 베개 삼아 베고 잠."}],
  "轟": [{w:"轟發",r:"굉발",d:"몹시 요란한 소리를 내면서 폭발함."},{w:"轟笑",r:"굉소",d:"큰 소리로 웃음."}],
  "宏": [{w:"宏圖",r:"굉도",d:"굉장한 계획."},{w:"宏業",r:"굉업",d:"매우 큰 사업."}],
  "攪": [{w:"攪亂",r:"교란",d:"마음이나 상황 따위를 뒤흔들어서 어지럽고 혼란하게 함."},{w:"攪拌",r:"교반",d:"휘저어 섞음."}],
  "咬": [{w:"咬裂",r:"교열",d:"물어뜯어 찢음."},{w:"咬頭",r:"교두",d:"앞니를 제외한 치아의 씹는 면에 솟아오른 부분."}],
  "喬": [{w:"喬林",r:"교림",d:"키가 큰 나무가 우거진 숲."},{w:"喬幹",r:"교간",d:"높고 큰 나무의 줄기."}],
  "驕": [{w:"驕色",r:"교색",d:"잘난 체하며 겸손함이 없이 뽐내는 낯빛."},{w:"驕心",r:"교심",d:"잘난 체하며 뽐내는 마음."}],
  "轎": [{w:"獨轎",r:"독교",d:"말 한 마리가 끄는 가마."},{w:"涼轎",r:"양교",d:"선가(禪家)에서, 장로(長老)가 타는 손수레."}],
  "蛟": [{w:"潛蛟",r:"잠교",d:"깊은 물속에 잠겨 있는 교룡(蛟龍)."},{w:"蛟龍",r:"교룡",d:"상상 속에 등장하는 동물의 하나. 모양이 뱀과 같고 몸의 길이가 한 길이 넘으며 넓적한 네발이 있고, 가슴은 붉고 등에는 푸른 무늬가 있으며 옆구리와 배는 비단처럼 부드럽고 눈썹으로 교미하여 알을 낳는다고 한다."}],
  "皎": [{w:"皎月",r:"교월",d:"희고 밝은 달."},{w:"皎鏡",r:"교경",d:"밝은 거울이라는 뜻으로, ‘달’을 비유적으로 이르는 말."}],
  "狡": [{w:"狡童",r:"교동",d:"교활한 아이."},{w:"狡吏",r:"교리",d:"교활한 관리."}],
  "嬌": [{w:"嬌面",r:"교면",d:"교태가 있는 얼굴."},{w:"嬌音",r:"교음",d:"여자의 간드러지는 소리."}],
  "矩": [{w:"輪矩",r:"윤구",d:"자동차에서, 오른쪽과 왼쪽에 있는 두 바퀴 사이의 거리. 이중 바퀴인 경우는 두 바퀴의 중심에서 중심까지의 거리를 이른다."},{w:"東矩",r:"동구",d:"외행성이 태양의 동쪽에 있어 황경(黃經)의 차이가 90도인 시기. 또는 그 자리."}],
  "駒": [{w:"隙駒",r:"극구",d:"달리는 말을 문틈으로 본다는 뜻으로, 세월이 빨리 지나감을 이르는 말."},{w:"駒板",r:"구판",d:"베를 맬 때, 실을 켕기는 기구. 돌을 올려놓으며 끌리게 되어 있다."}],
  "鳩": [{w:"鳩便",r:"구편",d:"길들인 비둘기를 이용하여 통신함. 또는 그 통신."},{w:"鳩集",r:"구집",d:"한데 모음."}],
  "舅": [{w:"國舅",r:"국구",d:"임금의 장인."},{w:"舅母",r:"구모",d:"외삼촌의 아내."}],
  "枸": [{w:"枸木",r:"구목",d:"굽은 나무."},{w:"枸骨",r:"구골",d:"호랑가시나무의 열매를 한방에서 이르는 말."}],
  "廏": [{w:"廏肥",r:"구비",d:"외양간에서 쳐낸 두엄."},{w:"馬廏",r:"마구",d:"말을 가두어 기르는 곳."}],
  "寇": [{w:"侵寇",r:"침구",d:"침입하여 노략질함."},{w:"寇奪",r:"구탈",d:"사람을 해치고 재물을 약탈함."}],
