  "衢": [{w:"昏衢",r:"혼구",d:"어둑어둑한 저녁의 거리."},{w:"通衢",r:"통구",d:"통행하는 길."}],
  "鉤": [{w:"雙鉤",r:"쌍구",d:"글씨를 베낄 때, 가는 선으로 글자의 윤곽을 그려 내는 법."},{w:"呑鉤",r:"탄구",d:"고기가 낚싯바늘을 묾."}],
  "臼": [{w:"石臼",r:"석구",d:"돌의 가운데 부분을 오목하게 파서 만든 절구."},{w:"臼磨",r:"구마",d:"곡식을 빻거나 찧으며 떡을 치기도 하는 기구. 통나무나 돌, 쇠 따위를 속이 우묵하게 만들어 곡식 따위를 넣고 절굿공이로 빻거나 찧는다."}],
  "毆": [{w:"毆打",r:"구타",d:"사람이나 짐승을 함부로 치고 때림."},{w:"毆罵",r:"구매",d:"때리고 욕함."}],
  "溝": [{w:"溝瀆",r:"구독",d:"개천과 수렁을 아울러 이르는 말."},{w:"側溝",r:"측구",d:"길바닥의 물이 잘 빠지도록 차도와 인도의 경계선을 따라 만든 얕은 도랑."}],
