  "慄": [{w:"戰慄",r:"전률",d:"몹시 무섭거나 두려워 몸이 벌벌 떨림. ⇒규범 표기는 ‘전율’이다."},{w:"震慄",r:"진율",d:"무섭고 두려워서 몸을 떪."}],
  "肋": [{w:"肋材",r:"늑재",d:"선박의 늑골을 이루는 재료."},{w:"肋板",r:"늑판",d:"배 밑바닥을 견고하게 하기 위하여 선체의 활 모양으로 굽은 부분 아래에서 늑골 사이에 끼워 넣는 철강판."}],
  "勒": [{w:"水勒",r:"수륵",d:"거친 재갈."},{w:"勒住",r:"늑주",d:"억지로 머무르거나 살게 함."}],
  "凜": [{w:"凜秋",r:"늠추",d:"서늘한 가을."},{w:"凜慄",r:"늠률",d:"추위에 떪."}],
  "稜": [{w:"三稜",r:"삼릉",d:"세 모서리. 또는 세 모서리가 있는 물건."},{w:"稜線",r:"능선",d:"산등성이를 따라 죽 이어진 선."}],
  "綾": [{w:"綾羅",r:"능라",d:"두꺼운 비단과 얇은 비단."},{w:"白綾",r:"백릉",d:"흰빛의 얇은 비단."}],
  "凌": [{w:"凌室",r:"능실",d:"얼음을 저장하여 두는 곳."},{w:"凌上",r:"능상",d:"아랫사람이 윗사람을 업신여김."}],
  "菱": [{w:"菱米",r:"능미",d:"마름 열매의 속살."},{w:"菱鐵",r:"능철",d:"끝이 송곳처럼 뾰족한 네 개의 발을 가진 쇠못. 도둑이나 적을 막기 위하여 흩어 두었다."}],
  "悧": [{w:"怜悧",r:"영리",d:"‘영리하다’의 어근."}],
  "籬": [{w:"缺籬",r:"결리",d:"귀퉁이 한쪽이 부서진 울타리."},{w:"竹籬",r:"죽리",d:"굵은 대나무를 쪼개서 결어 만들거나, 대를 심어 이루어진 울타리."}],
  "釐": [{w:"釐革",r:"이혁",d:"뜯어고쳐 정리함."},{w:"釐正",r:"이정",d:"문서나 글을 정리하여 바로잡음."}],
  "俚": [{w:"俚歌",r:"이가",d:"항간에 유행하는 속된 노래."},{w:"俚語",r:"이어",d:"항간(巷間)에 떠돌며 쓰이는 속된 말."}],
  "裡": [{w:"帖裡",r:"첩리",d:"무관이 입던 공복(公服). 직령(直領)으로서, 허리에 주름이 잡히고 큰 소매가 달렸는데, 당상관은 남색이고 당하관은 분홍색이다."},{w:"庫裡",r:"고리",d:"절에서, 부처에게 올리는 밥이나 승려의 음식을 마련하는 곳."}],
  "痢": [{w:"冷痢",r:"냉리",d:"몸이 차고 습하여 생긴 이질. 배가 아프고 곱똥이 나오며 뒤가 땅긴다."},{w:"毒痢",r:"독리",d:"열독(熱毒)으로 피고름이 섞인 설사를 하는 이질."}],
  "罹": [{w:"揮罹",r:"휘리",d:"후릿그물을 둘러쳐서 물고기를 잡음."},{w:"橫罹",r:"횡리",d:"뜻밖에 재앙을 당함."}],
  "吝": [{w:"吝嗇",r:"인색",d:"재물을 아끼는 태도가 몹시 지나침."},{w:"儉吝",r:"검린",d:"‘검린하다’의 어근."}],
  "鱗": [{w:"魚鱗",r:"어린",d:"물고기의 비늘."},{w:"小鱗",r:"소린",d:"작은 비늘."}],
  "燐": [{w:"鬼燐",r:"귀린",d:"밤에 무덤이나 축축한 땅 또는 고목이나 낡고 오래된 집에서 인 따위의 작용으로 저절로 번쩍이는 푸른빛의 불꽃."},{w:"燐光",r:"인광",d:"복사 광선에 노출된 물질이, 자극하는 복사 에너지가 사라진 후에도 계속하여 내는 발광. 흰인 따위에서 볼 수 있다."}],
  "躪": [{w:"征躪",r:"정린",d:"남을 정복하여 짓밟음."},{w:"蹂躪",r:"유린",d:"남의 권리나 인격을 짓밟음."}],
  "淋": [{w:"淋巴",r:"임파",d:"‘림프’의 음역어."},{w:"淋瀝",r:"임력",d:"물방울 또는 빗방울이 뚝뚝 떨어지는 모양."}],
  "笠": [{w:"着笠",r:"착립",d:"초립이나 삿갓을 씀."},{w:"黑笠",r:"흑립",d:"옻칠을 한 갓. 어두운 흑갈색이다."}],
  "粒": [{w:"顆粒",r:"과립",d:"둥글고 작은 알갱이."},{w:"小粒",r:"소립",d:"작은 알갱이."}],
  "寞": [{w:"寂寞",r:"적막",d:"고요하고 쓸쓸함."},{w:"落寞",r:"낙막",d:"‘낙막하다’의 어근."}],
  "輓": [{w:"輓歌",r:"만가",d:"상여꾼들이 상여를 메고 가면서 부르는 구슬픈 소리."},{w:"輓馬",r:"만마",d:"수레를 끄는 말."}],
  "饅": [{w:"饅頭",r:"만두",d:"밀가루 따위를 반죽하여 소를 넣어 빚은 음식. 삶거나 찌거나 기름에 튀겨 조리하는데, 떡국에 넣기도 하고 국을 만들어 먹기도 한다."},{w:"土饅頭",r:"토만두",d:"‘무덤’을 속되게 이르는 말."}],
  "蔓": [{w:"綠蔓",r:"녹만",d:"푸른 풀덤불."},{w:"刪蔓",r:"산만",d:"편지에서, 인사는 생략하고 바로 할 말을 적겠다는 뜻으로 첫머리에 쓰는 말."}],
  "鰻": [{w:"風鰻",r:"풍만",d:"말린 뱀장어."},{w:"養鰻",r:"양만",d:"뱀장어를 기름."}],
  "卍": [{w:"卍字",r:"만자",d:"‘卍’ 자 모양으로 된 표지."},{w:"卍字紋",r:"만자문",d:"‘卍’ 자 모양으로 된 무늬."}],
  "彎": [{w:"彎屈",r:"만굴",d:"활 모양으로 굽음."},{w:"彎環",r:"만환",d:"둥근 모양. 또는 그 모양의 물건."}],
  "挽": [{w:"挽回",r:"만회",d:"바로잡아 회복함."},{w:"挽住",r:"만주",d:"붙들고 못 하게 말림."}],
  "瞞": [{w:"瞞着",r:"만착",d:"남의 눈을 속여 넘김."},{w:"欺瞞",r:"기만",d:"남을 속여 넘김."}],
  "抹": [{w:"一抹",r:"일말",d:"한 번 칠한다는 뜻으로, ‘약간’을 이르는 말."},{w:"抹去",r:"말거",d:"기록이나 사실 따위를 지워 없애거나 뭉개 버림."}],
