  "芒": [{w:"光芒",r:"광망",d:"비치는 빛살."},{w:"星芒",r:"성망",d:"별의 반짝이는 빛."}],
  "惘": [{w:"悵惘",r:"창망",d:"‘창망하다’의 어근."},{w:"憫惘",r:"민망",d:"‘민망하다’의 어근."}],
  "煤": [{w:"煙煤",r:"연매",d:"연기 속에 섞여 나오는 검은 가루. 또는 구들장 밑이나 굴뚝 따위에 끈끈하게 엉키어 붙은 그을음."},{w:"煤田",r:"매전",d:"석탄이 묻혀 있는 땅."}],
  "罵": [{w:"面罵",r:"면매",d:"면전(面前)에서 꾸짖음."},{w:"惡罵",r:"악매",d:"모질게 꾸짖음. 또는 그런 꾸지람."}],
  "邁": [{w:"邁德",r:"매덕",d:"힘써 덕을 닦음."},{w:"俊邁",r:"준매",d:"재주와 지혜가 매우 뛰어남. 또는 그런 사람."}],
  "呆": [{w:"呆病",r:"매병",d:"정신병의 하나. 정신 상태가 온전하지 못하여 하루 종일 말을 하지 않고, 음식을 먹지 않으며, 갑자기 웃기도 하고 울기도 하며, 사물을 잘 구분하지 못한다."},{w:"納呆",r:"납매",d:"위가 음식을 잘 받아들이지 못하는 증상. 소화가 잘되지 않고 입맛이 없어진다."}],
  "昧": [{w:"昧臣",r:"매신",d:"세상 물정에 어둡고 어리석은 신하."},{w:"昧谷",r:"매곡",d:"해가 지는 골짜기라는 뜻으로, 날이 저묾을 비유적으로 이르는 말."}],
  "寐": [{w:"夢寐",r:"몽매",d:"잠을 자면서 꿈을 꿈. 또는 그 꿈."},{w:"監寐",r:"감매",d:"자나 깨나 언제나."}],
