  "眄": [{w:"右眄",r:"우면",d:"고개를 오른쪽으로 돌려 봄."},{w:"仰眄",r:"앙면",d:"존경하는 마음으로 우러러봄."}],
  "緬": [{w:"緬憶",r:"면억",d:"지난 일을 돌이켜 생각함."},{w:"緬禮",r:"면례",d:"무덤을 옮겨서 다시 장사를 지냄. 또는 그런 일."}],
  "麪": [{w:"食麵",r:"식면",d:"밀가루에 효모를 넣고 반죽하여 구워 낸 주식용 빵. 직육면체 모양의 빵으로, 위가 볼록볼록하기도 하며 주로 속에 아무것도 넣지 않고 구워 낸다."},{w:"麵米",r:"면미",d:"밀가루와 메밀가루를 기계로 눌러서 쌀알처럼 만든 것."}],
