  "皿": [{w:"皿秤",r:"명칭",d:"접시 모양의 판에 물건을 올려놓고 무게를 다는 저울. 약품, 귀금속 따위의 무게를 달 때 쓴다."},{w:"皿斗",r:"명두",d:"기둥 위를 장식하며 공포를 받치는 넓적하고 네모진 나무."}],
  "螟": [{w:"螟蟲",r:"명충",d:"명나방과의 곤충을 통틀어 이르는 말."},{w:"螟嗣",r:"명사",d:"타성(他姓)에서 맞아들인 양자(養子)를 이르는 말."}],
  "酩": [{w:"酩酊",r:"명정",d:"몸을 가눌 수 없을 정도로 술에 몹시 취함."}],
  "袂": [{w:"袂口",r:"몌구",d:"옷소매의 아가리."},{w:"短袂",r:"단몌",d:"짧은 소매."}],
  "摸": [{w:"臨摸",r:"임모",d:"글씨나 그림 따위를 본을 보고 그대로 옮겨 쓰거나 그림."},{w:"摸索",r:"모색",d:"일이나 사건 따위를 해결할 수 있는 방법이나 실마리를 더듬어 찾음."}],
