  "杳": [{w:"杳然",r:"묘연",d:"‘묘연하다’의 어근."},{w:"杳乎",r:"묘호",d:"‘묘호하다’의 어근."}],
  "渺": [{w:"渺漫",r:"묘만",d:"끝없이 넓음."},{w:"渺遠",r:"묘원",d:"‘묘원하다’의 어근."}],
  "巫": [{w:"巫俗",r:"무속",d:"무당과 관련된 풍속."},{w:"巫夫",r:"무부",d:"무당의 남편."}],
  "蕪": [{w:"靑蕪",r:"청무",d:"푸르고 무성한 풀. 또는 그 풀이 자라는 땅."},{w:"平蕪",r:"평무",d:"잡초가 무성한 편평한 들."}],
  "畝": [{w:"畝背",r:"무배",d:"‘묘배’의 원말."},{w:"田畝",r:"전묘",d:"밭의 고랑 사이에 흙을 높게 올려서 만든 두둑한 곳."}],
  "毋": [{w:"毋追",r:"무퇴",d:"중국 하나라 때의 관(冠)."}],
