  "鴛": [{w:"鴛瓦",r:"원와",d:"암키와와 수키와가 짝을 이룬 것. 또는 모양이 원앙과 비슷한 기와."},{w:"鴛鴦",r:"원앙",d:"오릿과의 물새. 몸의 길이는 40~45cm이고 부리는 짧고 끝에는 손톱 같은 돌기가 있다. 수컷의 뒷머리에는 긴 관모가 있고 날개 안의 깃털은 부채꼴같이 퍼져 있다. 여름 깃은 머리와 목이 회갈색, 등은 감람색, 가슴은 갈색 바탕에 흰 점이 있다. 여름에는 암수가 거의 같은 빛이나 겨울에는 수컷의 볼기와 목이 붉은 갈색, 가슴이 자주색이다. 한국, 일본, 중국, 대만 등지에 분포한다. 우리나라 천연기념물이다."}],
