  "膺": [{w:"服膺",r:"복응",d:"교훈 따위를 마음에 간직하여 잠시도 잊지 아니함."},{w:"膺懲",r:"응징",d:"잘못을 깨우쳐 뉘우치도록 징계함."}],
  "毅": [{w:"猛毅",r:"맹의",d:"뜻이나 의지가 강하여 불의에 굽히지 않는 일."},{w:"忠毅",r:"충의",d:"충성스럽고 꿋꿋함."}],
  "椅": [{w:"交椅",r:"교의",d:"사람이 걸터앉는 데 쓰는 기구. 보통 뒤에 등받이가 있고 종류가 다양하다."},{w:"竹椅",r:"죽의",d:"대를 결어서 만든 의자."}],
  "擬": [{w:"擬古",r:"의고",d:"옛것을 본뜸."},{w:"擬作",r:"의작",d:"모방하여 만듦. 또는 그런 작품."}],
  "誼": [{w:"世誼",r:"세의",d:"대대로 사귀어 온 정(情)."},{w:"友誼",r:"우의",d:"친구 사이의 정의(情誼)."}],
  "餌": [{w:"食餌",r:"식이",d:"동물이 살아가기 위하여 먹어야 할 거리. 또는 사육하는 가축에게 주는 먹을거리."},{w:"藥餌",r:"약이",d:"약이 되는 음식."}],
  "姨": [{w:"姨從",r:"이종",d:"이모의 자녀를 이르는 말."},{w:"姨姪",r:"이질",d:"언니나 여동생의 아들딸."}],
