  "蚓": [{w:"春蚓",r:"춘인",d:"초봄에 지상으로 기어 나오는 지렁이."},{w:"蚯蚓腫",r:"구인종",d:"지렁이 모양으로 융기된 형태 또는 종양."}],
  "靭": [{w:"靭帶",r:"인대",d:"관절의 뼈 사이와 관절 주위에 있는, 노끈이나 띠 모양의 결합 조직. 관절을 보강하고 관절의 운동을 제한하는 작용을 한다."},{w:"靭性",r:"인성",d:"재료의 질긴 정도. 외부에서 잡아당기거나 누르는 힘 때문에 갈라지거나 늘어나지 않고 견디는 성질을 이른다."}],
  "咽": [{w:"感咽",r:"감열",d:"감격하여 목메어 욺."},{w:"哀咽",r:"애열",d:"슬퍼서 목이 멤. 또는 그렇게 욺."}],
  "湮": [{w:"湮滅",r:"인멸",d:"자취도 없이 모두 없어짐. 또는 그렇게 없앰."},{w:"湮沒",r:"인몰",d:"자취도 없이 모두 없어짐. 또는 그렇게 없앰."}],
  "溢": [{w:"溢血",r:"일혈",d:"‘출혈’의 전 용어."},{w:"充溢",r:"충일",d:"가득 차서 넘침."}],
  "佚": [{w:"佚民",r:"일민",d:"세상을 등지고 숨어 사는 백성."},{w:"佚遊",r:"일유",d:"마음대로 편안히 즐기고 놂."}],
  "剩": [{w:"剩餘",r:"잉여",d:"쓰고 난 후 남은 것."},{w:"過剩",r:"과잉",d:"예정하거나 필요한 수량보다 많아 남음."}],
  "孕": [{w:"孕母",r:"잉모",d:"아이를 밴 여자."},{w:"育孕",r:"육잉",d:"아이를 뱀."}],
