  "仔": [{w:"仔豚",r:"자돈",d:"새끼 돼지."},{w:"仔蟲",r:"자충",d:"알에서 나온 후 아직 다 자라지 아니한 벌레."}],
  "蔗": [{w:"蔗境",r:"자경",d:"담화나 문장 또는 사건 따위가 점점 재미있어지는 대목."},{w:"甘蔗",r:"감자",d:"볏과의 여러해살이풀. 높이는 2~4미터이며, 수수와 비슷하나 마디와 마디 사이가 짧다. 잎은 가늘고 긴데 긴 선 모양이다. 줄기의 꼭대기에 회백색 꽃이 원추(圓錐) 화서로 핀다. 줄기에서 짠 즙으로 설탕을 만든다. 인도 갠지스강 유역이 원산지로 열대, 아열대에서 재배한다."}],
  "炙": [{w:"五炙",r:"오적",d:"궁중에서 제상에 오르는 다섯 가지의 적. 소적, 육적, 어적, 봉적, 채소적을 이른다."},{w:"足炙",r:"족적",d:"삶은 쇠족을 큼직하게 저미어 진장과 기름을 바르고 깨소금, 후춧가루 따위를 쳐서 한데 주물러 불에 구운 적."}],
  "煮": [{w:"煮乾",r:"자건",d:"삶아서 말림."},{w:"煮汁",r:"자즙",d:"끓인 즙."}],
  "藉": [{w:"慰藉",r:"위자",d:"위로하고 도와줌."},{w:"藉托",r:"자탁",d:"다른 구실을 내세워 핑계를 댐."}],
  "瓷": [{w:"瓷燈",r:"자등",d:"백토(白土) 따위의 흙으로 사기처럼 구워 만든 등잔."},{w:"瓷塔",r:"자탑",d:"자기(瓷器)로 만든 탑."}],
  "炸": [{w:"炸發",r:"작발",d:"화약이 터짐."},{w:"炸彈",r:"작탄",d:"작약(炸藥)을 넣은 탄환."}],
  "勺": [{w:"銀勺",r:"은작",d:"은으로 만든 구기."},{w:"勺水",r:"작수",d:"한 작의 물이라는 뜻으로, 한 모금의 물을 이르는 말."}],
  "灼": [{w:"白灼",r:"백작",d:"불꽃이나 빛살 따위가 하얗게 빛남."},{w:"灼熱",r:"작열",d:"불 따위가 이글이글 뜨겁게 타오름."}],
