  "嚼": [{w:"咀嚼",r:"저작",d:"음식을 입에 넣고 씹음."},{w:"爛嚼",r:"난작",d:"음식을 잘 씹음."}],
  "芍": [{w:"芍藥",r:"작약",d:"작약과의 여러해살이풀을 통틀어 이르는 말. 꽃이 크고 아름다워 정원에 관상용으로 재배한다. 백작약, 산작약, 적작약, 호작약 따위가 있다."},{w:"贈芍",r:"증작",d:"작약(芍藥)을 선물로 바친다는 뜻으로, 남녀가 서로 사랑을 표시함을 비유적으로 이르는 말."}],
  "雀": [{w:"雀羅",r:"작라",d:"새를 잡는 데 쓰는 그물."},{w:"群雀",r:"군작",d:"무리를 지은 참새라는 뜻으로, 평범한 뭇사람을 이르는 말."}],
  "鵲": [{w:"鵲語",r:"작어",d:"까치의 지저귀는 소리. 흔히 기쁜 일이 있을 조짐으로 여긴다."},{w:"鵲報",r:"작보",d:"까치가 지저귀는 소리라는 뜻으로, ‘길조’를 이르는 말."}],
