  "棧": [{w:"棧道",r:"잔도",d:"험한 벼랑 같은 곳에 낸 길. 선반처럼 달아서 낸다."},{w:"木棧",r:"목잔",d:"나무로 사다리처럼 놓은 길."}],
  "箴": [{w:"動箴",r:"동잠",d:"사물잠(四勿箴)의 하나. 예(禮)가 아니면 움직이지 말라는 경계이다."},{w:"視箴",r:"시잠",d:"사물잠(四勿箴)의 하나. 예(禮)가 아니면 보지 말라는 경계이다."}],
  "簪": [{w:"金簪",r:"금잠",d:"금으로 만든 비녀."},{w:"玉簪",r:"옥잠",d:"옥으로 만든 비녀."}],
  "檣": [{w:"前檣",r:"전장",d:"뱃머리 쪽에 있는 돛대."},{w:"船檣",r:"선장",d:"돛을 달기 위하여 배 바닥에 세운 기둥."}],
  "薔": [{w:"薔薇",r:"장미",d:"이장희 작사·작곡의 대중가요. 1979년에 발표된 사랑과 평화의 앨범에 수록되어 있다."},{w:"白薔薇",r:"백장미",d:"흰색 장미."}],
  "漿": [{w:"乳漿",r:"유장",d:"젖 성분에서 단백질과 지방을 빼고 남은 부분."},{w:"牛漿",r:"우장",d:"천연두를 예방하기 위하여 우두에서 뽑아낸 면역성 액체."}],
