  "杖": [{w:"杖責",r:"장책",d:"태형으로 벌함."},{w:"杖竹",r:"장죽",d:"지팡이로 쓰는 대나무."}],
  "匠": [{w:"金匠",r:"금장",d:"금속에 세공을 하는 일. 또는 그 일에 종사하는 사람."},{w:"名匠",r:"명장",d:"기술이 뛰어나 이름난 장인."}],
  "仗": [{w:"天仗",r:"천장",d:"임금의 의장(儀仗)."},{w:"甲仗",r:"갑장",d:"갑옷과 창검 따위의 병기."}],
  "齋": [{w:"齋七",r:"재칠",d:"사람이 죽은 뒤 49일 동안 이레마다 행하는 재."},{w:"入齋",r:"입재",d:"제사 전날에 음식과 행동을 조심하며 재계(齋戒)하는 일."}],
  "滓": [{w:"魚滓",r:"어재",d:"살을 발라내었거나 기름을 짜고 난 물고기의 찌꺼기. 주로 비료로 쓴다."},{w:"壓滓",r:"압재",d:"눌러 짜고 남은 찌끼."}],
  "錚": [{w:"錚盤",r:"쟁반",d:"높이가 얕고 동글납작하거나 네모난, 넓고 큰 그릇."},{w:"擊錚",r:"격쟁",d:"징이나 꽹과리를 침."}],
  "狙": [{w:"狙擊",r:"저격",d:"일정한 대상을 노려서 치거나 총을 쏨."},{w:"狙公",r:"저공",d:"‘원숭이’를 달리 이르는 말."}],
  "豬": [{w:"豬毛",r:"저모",d:"돼지의 털."},{w:"豬肉",r:"저육",d:"‘제육’의 원말."}],
  "箸": [{w:"下箸",r:"하저",d:"젓가락을 댄다는 뜻으로, 음식을 먹음을 이르는 말."},{w:"火箸",r:"화저",d:"화로에 꽂아 두고 불덩이를 집거나 불을 헤치는 데 쓰는 쇠로 만든 젓가락."}],
  "咀": [{w:"咀嚼",r:"저작",d:"음식을 입에 넣고 씹음."},{w:"咀嚼力",r:"저작력",d:"음식을 입에 넣고 씹는 힘."}],
  "詛": [{w:"詛呪",r:"저주",d:"남에게 재앙이나 불행이 일어나도록 빌고 바람. 또는 그렇게 하여서 일어난 재앙이나 불행."},{w:"呪詛",r:"주저",d:"남에게 재앙이나 불행이 일어나도록 빌고 바람. 또는 그렇게 하여서 일어난 재앙이나 불행."}],
  "躇": [{w:"躊躇",r:"주저",d:"머뭇거리며 망설임."},{w:"躊躇痕",r:"주저흔",d:"자살하려는 사람이 한 번에 치명상을 만들지 못하고 여러 차례 자해하여 생긴 흔적."}],
  "邸": [{w:"自邸",r:"자저",d:"자기의 저택."},{w:"新邸",r:"신저",d:"새 저택."}],
  "觝": [{w:"角觝",r:"각저",d:"고구려 때에, 하류층에서 하던 놀이의 하나. 두 사람이 씨름하듯이 맞붙어 힘을 겨루거나 또는 여러 가지 기예와 활쏘기, 말타기 따위를 겨루었다."},{w:"蝸角觝",r:"와각저",d:"하찮은 일로 벌이는 싸움을 비유적으로 이르는 말."}],
  "嫡": [{w:"嫡女",r:"적녀",d:"정실이 낳은 딸."},{w:"嫡兄",r:"적형",d:"첩에게서 난 아들이 정실에게서 난 형을 이르는 말."}],
  "謫": [{w:"謫客",r:"적객",d:"귀양살이를 하는 사람."},{w:"謫落",r:"적락",d:"죄를 지어 관직에서 퇴직당함."}],
  "狄": [{w:"狄人",r:"적인",d:"중국 북쪽의 야만족."},{w:"戎狄",r:"융적",d:"중국에서 서쪽 오랑캐와 북쪽 오랑캐를 아울러 이르던 말."}],
  "迹": [{w:"表迹",r:"표적",d:"겉으로 드러난 자취."},{w:"慘迹",r:"참적",d:"참혹한 흔적."}],
  "塡": [{w:"充塡",r:"충전",d:"메워서 채움."},{w:"塡充",r:"전충",d:"빈 곳을 채워 메움."}],
