  "菖": [{w:"菖蒲",r:"창포",d:"천남성과의 여러해살이풀. 높이는 70~100cm이며, 온몸에 향기가 있다. 뿌리줄기는 통통하고 마디가 많으며, 잎은 뿌리줄기에서 뭉쳐나고 가는 선 모양이다. 6~7월에 연한 노란색을 띤 녹색 꽃이 꽃줄기 끝에 수상(穗狀) 화서로 피고 열매는 긴 타원형의 붉은 장과(漿果)를 맺는다. 뿌리는 약용하고 단오에 창포물을 만들어 머리를 감거나 술을 빚는다. 연못이나 도랑의 가장자리에서 자라는데 한국, 일본, 동아시아, 시베리아, 말레이시아, 인도, 북아메리카 등지에 분포한다."},{w:"白菖",r:"백창",d:"창포 품종의 하나. 뿌리가 굵고 살지며 희고 마디가 성기다. 늪에서 난다."}],
