  "貂": [{w:"貂皮",r:"초피",d:"담비 종류 동물의 모피를 통틀어 이르는 말. 일반적으로 고급 모피로 인정받고 있으며 품질에 따라 검은담비의 모피인 ‘잘’을 상등으로 치고, 노랑담비의 모피인 ‘돈피’와 유럽소나무담비의 모피인 ‘초서피’를 중등으로 치며, 흰담비의 모피인 ‘백초피’를 하등으로 친다."},{w:"續貂",r:"속초",d:"훌륭한 사람이나 사물에 변변하지 못한 사람이나 사물이 뒤따름."}],
  "礁": [{w:"坐礁",r:"좌초",d:"배가 암초에 얹힘."},{w:"礁標",r:"초표",d:"바닷길의 안전을 위하여 암초 같은 곳에 세우는 경계표지."}],
  "硝": [{w:"朴硝",r:"박초",d:"초석(硝石)을 한 번 구워 만든 약재. 이뇨제로 쓴다."},{w:"焰硝",r:"염초",d:"열, 전기,충격 따위의 가벼운 자극에 의하여 순간적으로 연소 또는 분해 반응을 일으키고 높은 온도의 열과 압력을 가진 가스를 발생시켜 파괴, 추진 따위의 작용을 행하는 화합물이나 혼합물을 통틀어 이르는 말."}],
  "憔": [{w:"憔容",r:"초용",d:"말라빠진 모습."},{w:"焦憔",r:"초초",d:"애를 태우며 근심함."}],
  "醋": [{w:"食醋",r:"식초",d:"액체 조미료의 하나. 약간의 초산이 들어 있어 신맛이 난다."},{w:"醋蜜",r:"초밀",d:"식초와 꿀을 섞은 것."}],
  "蕉": [{w:"蕉布",r:"초포",d:"파초의 섬유로 짠 베."},{w:"蕉葛",r:"초갈",d:"파초의 섬유로 짠 베."}],
  "樵": [{w:"樵隱",r:"초은",d:"나무꾼과 은둔자를 아울러 이르는 말."},{w:"樵奴",r:"초노",d:"땔나무를 하는 종."}],
  "梢": [{w:"末梢",r:"말초",d:"나뭇가지의 끝에서 갈리어 나간 가는 가지."},{w:"梢殺",r:"초살",d:"수간의 끝 쪽이 가늘게 된 모양. 형수의 값이 적다."}],
