  "炒": [{w:"鴨炒",r:"압초",d:"오리고기를 잘게 토막 쳐서 양념하여 볶은 음식."},{w:"土炒",r:"토초",d:"약재를 황토물에 적셔서 불에 볶는 일."}],
  "囑": [{w:"委囑",r:"위촉",d:"어떤 일을 남에게 부탁하여 맡게 함."},{w:"囑託",r:"촉탁",d:"일을 부탁하여 맡김."}],
  "忖": [{w:"忖度",r:"촌탁",d:"남의 마음을 미루어서 헤아림."}],
  "叢": [{w:"叢石",r:"총석",d:"총총하게 서 있는 바윗돌."},{w:"叢林",r:"총림",d:"잡목이 우거진 숲."}],
  "塚": [{w:"大冢",r:"대총",d:"규모가 큰 무덤."},{w:"冢弟",r:"총제",d:"임금의 동생을 높여 이르던 말."}],
  "寵": [{w:"寵人",r:"총인",d:"특별한 사랑과 귀염을 받는 사람."},{w:"男寵",r:"남총",d:"예쁘게 생긴 남자가 특별한 사랑을 받는 일."}],
  "撮": [{w:"撮影",r:"촬영",d:"사람, 사물, 풍경 따위를 사진이나 영화로 찍음."},{w:"一撮",r:"일촬",d:"한 줌이라는 뜻으로, 극히 적은 양을 이르는 말."}],
  "槌": [{w:"木槌",r:"목퇴",d:"나무로 만든 몽치."},{w:"紙槌",r:"지추",d:"중국에서 나는 화병(畫甁)의 하나. 목이 길게 생겼다."}],
  "樞": [{w:"中樞",r:"중추",d:"사물의 중심이 되는 중요한 부분."},{w:"樞密",r:"추밀",d:"군정(軍政)에 관한 중요한 사항."}],
  "芻": [{w:"馬芻",r:"마추",d:"말을 먹이기 위한 풀."},{w:"芻言",r:"추언",d:"꼴 베는 사람의 말이라는 뜻으로, 무식하고 비천한 사람의 말을 이르는 말."}],
  "墜": [{w:"失墜",r:"실추",d:"명예나 위신 따위를 떨어뜨리거나 잃음."},{w:"傾墜",r:"경추",d:"기울어져 떨어짐."}],
  "鰍": [{w:"鰍湯",r:"추탕",d:"고추장을 푼 육수에 미꾸라지를 통째로 넣고 두부, 유부, 호박, 고추, 양지머리 따위와 함께 끓인 국."},{w:"泥鰍",r:"이추",d:"미꾸릿과의 민물고기. 몸의 길이는 10~20cm이고 등은 푸른빛을 띤 검은색이며, 배는 흰색이고 검은 점이 많다. 몸은 가늘고 길며 몹시 미끄럽고 수염이 길다. 논, 개천, 못 따위의 흙 속에 사는데 가끔 수면에 떠올라 공기 호흡을 한다. 한국, 대만, 중국 등지에 분포한다."}],
  "鎚": [{w:"石鎚",r:"석추",d:"일본으로부터 도입하여 재배하고 있는 밤 품종의 하나. 숙기는 10월 상중순이다. 수세(樹勢)는 보통이고 풍산성이지만 우리나라 품종에 비해 단맛은 적은 편이다. 밤나무혹벌에 대한 내충성이 강하다."},{w:"空氣鎚",r:"공기추",d:"압축 공기의 힘으로 움직이는 기계 해머. 단조(鍛造) 작업을 하거나 말뚝, 리벳 따위를 박을 때 쓴다."}],
  "酋": [{w:"酋長",r:"추장",d:"원시 사회에서 생활 공동체를 통솔하고 대표하던 우두머리."},{w:"酋領",r:"추령",d:"원시 사회에서 생활 공동체를 통솔하고 대표하던 우두머리."}],
  "錐": [{w:"方錐",r:"방추",d:"날이 네모난 송곳."},{w:"毛錐",r:"모추",d:"짐승의 털로 만든 붓."}],
  "錘": [{w:"扇錘",r:"선추",d:"부채고리에 매어 다는 장식품."},{w:"秤錘",r:"칭추",d:"저울대 한쪽에 걸거나 저울판에 올려놓는, 일정한 무게의 쇠."}],
  "椎": [{w:"脊椎",r:"척추",d:"척추뼈로 이루어진 등마루."},{w:"椎剽",r:"추표",d:"사람을 때려 죽이고 금품을 빼앗음."}],
