  "贅": [{w:"贅物",r:"췌물",d:"쓸데없는 물건."},{w:"贅語",r:"췌어",d:"쓸데없는 군더더기 말."}],
  "悴": [{w:"悴容",r:"췌용",d:"초췌한 얼굴."},{w:"傷悴",r:"상췌",d:"마음이 상하여 얼굴이나 몸이 핏기 없이 파리하고 해쓱하여짐."}],
  "膵": [{w:"膵頭",r:"췌두",d:"샘창자의 오목한 곳에 접하여 있는 췌장의 오른쪽 부분."},{w:"膵體",r:"췌체",d:"췌장에서, 혈관에 의해 잘록해진 목과 꼬리 사이의 부분. 삼각기둥 모양과 비슷하다."}],
  "萃": [{w:"出萃",r:"출췌",d:"같은 무리 가운데에서 특별히 뛰어남."},{w:"拔萃",r:"발췌",d:"책, 글 따위에서 필요하거나 중요한 부분을 가려 뽑아냄. 또는 그런 내용."}],
  "娶": [{w:"娶室",r:"취실",d:"장가를 듦. 또는 아내를 맞거나 소실을 얻음."},{w:"成娶",r:"성취",d:"장가를 들어 아내를 얻음."}],
  "翠": [{w:"翠月",r:"취월",d:"남색과 비취색에 가까운 파르스름한 색. 또는 그런 물감."},{w:"翠空",r:"취공",d:"푸른 하늘."}],
  "脆": [{w:"脆怯",r:"취겁",d:"사람이 무르고 겁이 많아 쓰일 데가 없음."},{w:"脆弱",r:"취약",d:"무르고 약함."}],
