  "嗤": [{w:"嗤點",r:"치점",d:"비웃어 손가락질함."},{w:"嗤侮",r:"치모",d:"비웃으면서 깔보거나 멸시함."}],
  "痔": [{w:"痔痛",r:"치통",d:"치질 때문에 생기는 통증."},{w:"氣痔",r:"기치",d:"정신적인 고민이나 흥분 때문에 부어올라 아픈 치질."}],
  "侈": [{w:"外侈",r:"외치",d:"분수에 넘게 사치함."},{w:"侈心",r:"치심",d:"사치를 좋아하는 마음."}],
  "熾": [{w:"熾憤",r:"치분",d:"격렬히 분노함. 또는 그런 분노."},{w:"熾烈",r:"치열",d:"기세나 세력 따위가 불길같이 맹렬함."}],
