  "馳": [{w:"馳車",r:"치거",d:"달리는 수레. 또는 수레를 달리게 함."},{w:"馳進",r:"치진",d:"어른 앞으로 빨리 달려 나감."}],
  "勅": [{w:"勅敎",r:"칙교",d:"임금이 몸소 이름. 또는 그런 말씀이나 그것을 적은 포고문."},{w:"勅書",r:"칙서",d:"임금이 특정인에게 훈계하거나 알릴 내용을 적은 글이나 문서."}],
  "鍼": [{w:"一鍼",r:"일침",d:"침 한 대라는 뜻으로, 따끔한 충고나 경고를 이르는 말."},{w:"藥鍼",r:"약침",d:"의약과 침술을 아울러 이르는 말."}],
  "砧": [{w:"鐵砧",r:"철침",d:"대장간에서 불린 쇠를 올려놓고 두드릴 때 받침으로 쓰는 쇳덩이."},{w:"砧聲",r:"침성",d:"다듬이질 소리."}],
  "蟄": [{w:"病蟄",r:"병칩",d:"병으로 인하여 집에만 틀어박혀 있음."},{w:"蟄居",r:"칩거",d:"나가서 활동하지 아니하고 집 안에만 틀어박혀 있음."}],
  "秤": [{w:"秤量",r:"칭량",d:"저울로 무게를 닮."},{w:"小秤",r:"소칭",d:"작은 저울."}],
  "駝": [{w:"駝背",r:"타배",d:"낙타의 등."},{w:"駝荷",r:"타하",d:"낙타에 실은 짐."}],
  "楕": [{w:"楕圓",r:"타원",d:"평면 위의 두 정점(定點)에서의 거리의 합이 언제나 일정한 점의 자취. 정점과 정직선으로부터의 거리의 비가 일정한 점의 자취로, 이 두 정점을 타원의 초점이라고 하고, 정직선을 준선이라고 한다."},{w:"楕球",r:"타구",d:"타원형으로 된 구."}],
  "惰": [{w:"惰農",r:"타농",d:"게으른 농사꾼."},{w:"放惰",r:"방타",d:"방심하여 게을러짐."}],
  "唾": [{w:"寶唾",r:"보타",d:"좋은 글귀나 명언을 이르는 말."},{w:"唾血",r:"타혈",d:"침이나 가래에 섞여 나오는 피."}],
  "陀": [{w:"盤陀",r:"반타",d:"말, 나귀 따위의 등에 얹어서 사람이 타기에 편리하도록 만든 도구."},{w:"伽陀",r:"가타",d:"부처의 공덕이나 가르침을 찬탄하는 노래 글귀."}],
  "舵": [{w:"舵輪",r:"타륜",d:"손잡이가 달린 바퀴 모양의 장치. 배의 키를 움직이는 데 쓴다."},{w:"轉舵",r:"전타",d:"선박이나 비행기 따위의 방향키 각도를 바꿈. 또는 바꾸어 진로를 달리함."}],
  "擢": [{w:"登擢",r:"등탁",d:"인재를 뽑아 씀."},{w:"擢登",r:"탁등",d:"골라 뽑아서 벼슬에 오르게 함."}],
  "鐸": [{w:"馬鐸",r:"마탁",d:"종 모양으로 생기고 위에 꼭지가 달린, 말에 다는 방울."},{w:"風鐸",r:"풍탁",d:"처마 끝에 다는 작은 종. 속에는 붕어 모양의 쇳조각을 달아 바람이 부는 대로 흔들리면서 소리가 난다."}],
  "呑": [{w:"呑食",r:"탄식",d:"통째로 먹음."},{w:"呑下",r:"탄하",d:"알약이나 가루약 따위를 삼켜서 넘김."}],
  "坦": [{w:"平坦",r:"평탄",d:"바닥이 평평함."},{w:"坦白",r:"탄백",d:"숨김없이 있는 그대로 말함."}],
  "憚": [{w:"無憚",r:"무탄",d:"꺼리거나 미워하지 아니함."},{w:"忌憚",r:"기탄",d:"어렵고 불편하게 여겨 감추거나 피함."}],
  "綻": [{w:"破綻",r:"파탄",d:"찢어져 터짐."},{w:"綻破",r:"탄파",d:"찢어져 터짐."}],
  "眈": [{w:"眈眈",r:"탐탐",d:"위엄 있게 주시하고 있는 모양."}],
  "搭": [{w:"搭乘",r:"탑승",d:"배나 비행기, 차 따위에 올라탐."},{w:"搭載",r:"탑재",d:"배, 비행기, 차 따위에 물건을 실음."}],
  "宕": [{w:"巾宕",r:"건탕",d:"망건과 탕건을 아울러 이르는 말."},{w:"跌宕",r:"질탕",d:"신이 나서 정도가 지나치도록 흥겨움. 또는 그렇게 노는 짓."}],
  "蕩": [{w:"蕩平",r:"탕평",d:"난(亂)을 평정함."},{w:"放蕩",r:"방탕",d:"주색잡기에 빠져 행실이 좋지 못함."}],
  "笞": [{w:"掠笞",r:"약태",d:"매질하여 죄인을 다스림."},{w:"鞭笞",r:"편태",d:"때릴 때에 쓰는 가는 나뭇가지. 어린아이를 벌줄 때나 마소를 부릴 때 쓴다."}],
  "苔": [{w:"苔田",r:"태전",d:"바닷가에 김을 양식하기 위하여 마련한 곳."},{w:"舌苔",r:"설태",d:"혓바닥에 끼는 흰색이나 회색, 황갈색의 이끼 모양 물질."}],
  "跆": [{w:"跆拳",r:"태권",d:"우리나라 고유의 전통 무예를 바탕으로 한 운동. 또는 그 경기. 손과 발, 또는 몸의 각 부분을 사용하여 차기, 지르기, 막기 따위의 기술을 구사하면서 공격과 방어를 한다. 단체전과 개인전이 있으며 개인전은 체급별로 이루어진다."},{w:"跆拳舞",r:"태권무",d:"태권도의 기본 동작과 응용 동작을 에어로빅 동작과 연결하고 음악성과 율동성을 더해서 창안한 무용."}],
  "汰": [{w:"淘汰",r:"도태",d:"물건을 물에 넣고 일어서 좋은 것만 골라내고 불필요한 것을 가려서 버림."},{w:"見汰",r:"견태",d:"관직에서 파면됨."}],
  "撐": [{w:"撐木",r:"탱목",d:"물건이 쓰러지지 않게 받치어 세우는 나무."},{w:"撐天",r:"탱천",d:"하늘을 찌를 듯이 공중으로 높이 솟아오름."}],
