  "慟": [{w:"慟心",r:"통심",d:"몹시 비탄하는 마음."},{w:"慟泣",r:"통읍",d:"슬피 욺."}],
  "桶": [{w:"水桶",r:"수통",d:"물을 담아 두는 통."},{w:"小桶",r:"소통",d:"작은 통."}],
  "筒": [{w:"筒形",r:"통형",d:"둥글고 길며 속은 비고 양 끝이 열린 통 모양."},{w:"筆筒",r:"필통",d:"붓이나 필기구 따위를 꽂아 두는 통."}],
