  "爬": [{w:"爬蟲",r:"파충",d:"파충강의 동물을 일상적으로 통틀어 이르는 말."},{w:"爬行",r:"파행",d:"벌레나 짐승 따위가 기어다님."}],
  "琶": [{w:"琵琶",r:"비파",d:"동양 현악기의 하나. 몸체는 길이 60~90cm의 둥글고 긴 타원형이며, 자루는 곧고 짧다. 인도·중국을 거쳐 우리나라에 들어왔는데, 네 줄의 당비파와 다섯 줄의 향비파가 있다."},{w:"琵琶形",r:"비파형",d:"비파와 같은 모양."}],
  "芭": [{w:"芭椒",r:"파초",d:"초피나무의 과피를 한방에서 이르는 말. 성질은 따뜻하고 맛은 매우며, 심복통(心腹痛)·구토·설사 따위에 쓰인다."},{w:"芭蕉",r:"파초",d:"파초과의 여러해살이풀. 높이는 2미터 정도이며, 잎은 뭉쳐나고 긴 타원형이다. 여름에 노란색을 띤 흰색의 단성화(單性花)가 피고 열매는 육질의 원기둥 모양이다. 약재로 쓰고 관상용으로 재배한다. 중국이 원산지로 따뜻한 지방에서 자란다."}],
  "跛": [{w:"跛立",r:"피립",d:"한 다리는 들고 한 다리만으로 섬."},{w:"偏跛",r:"편파",d:"한쪽 다리가 짧거나 탈이 나서 뒤뚝뒤뚝 저는 사람."}],
  "婆": [{w:"村婆",r:"촌파",d:"시골에 사는 노파."},{w:"塔婆",r:"탑파",d:"사람의 무덤."}],
  "辦": [{w:"辦出",r:"판출",d:"돈이나 물건 따위를 변통하여 마련하여 냄."},{w:"應辦",r:"응판",d:"수요(需要)에 응하여 갖추어 댐."}],
  "沛": [{w:"沛澤",r:"패택",d:"비의 은택."},{w:"沛者",r:"패자",d:"고구려 때에, 왕을 보좌하여 국정을 두루 맡아보던 벼슬. 대로와 패자 가운데 하나만을 두었다."}],
  "牌": [{w:"牌木",r:"패목",d:"패(牌)를 단 말뚝."},{w:"同牌",r:"동패",d:"같은 동아리. 또는 같은 패."}],
