  "稗": [{w:"稗飯",r:"패반",d:"피로 지은 밥."},{w:"稗嶺",r:"패령",d:"추수하기 전, 피도 아직 패지 아니할 무렵에 농가의 식량 사정이 어려운 고비."}],
